using System;using System.Drawing;using System.Linq;using System.Windows.Forms;using System.IO;
namespace ServiceTool {internal static class LauncherSpacingTests {static System.Collections.Generic.IEnumerable<Control> All(Control p){foreach(Control c in p.Controls){yield return c;foreach(var n in All(c))yield return n;}}
[STAThread]static int Main(){try{int count=0;foreach(bool dark in new[]{false,true})foreach(float scale in new[]{1F,1.25F,1.5F,2F})using(var f=new ManagerHub()){f.SetTheme(dark,false);f.Show();if(scale!=1)f.Scale(new SizeF(scale,scale));for(int n=0;n<8;n++)Application.DoEvents();var cards=All(f).OfType<Card>().ToArray();var settings=cards.Single(c=>All(c).OfType<Label>().Any(l=>l.Text=="Первичные системные настройки"));foreach(var card in cards.Where(c=>c!=settings)){var a=card.RectangleToScreen(card.ClientRectangle);var b=settings.RectangleToScreen(settings.ClientRectangle);if(a.IntersectsWith(b)||a.Bottom>=b.Top)throw new Exception("Card overlaps settings at "+scale);count++;}foreach(var p in All(f).OfType<TableLayoutPanel>().Where(p=>p.ColumnCount==2&&p.RowCount==2)){foreach(Control c in p.Controls)if(c.Bottom>p.ClientSize.Height)throw new Exception("Module row exceeds viewport");count++;}using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher-"+dark+"-"+scale+".png"));}f.Close();}Console.WriteLine("PASS "+count+" launcher spacing checks, both themes and scales100-200%");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}}
